import * as core from '@actions/core';
export const registries = process.env['STATE_registries'] ? JSON.parse(process.env['STATE_registries']) : [];
export const logout = /true/i.test(process.env['STATE_logout'] || '');
export function setRegistries(registries) {
    core.saveState('registries', JSON.stringify(registries));
}
export function setLogout(logout) {
    core.saveState('logout', logout);
}
